-- 29 Atlas of the Deep: the camera, and which names show at which zoom.
-- The lettering is the engine's (world text in a distance-field font).
-- Generated by tools/gen_scenes.py with the tour's stops. Wheel: zoom toward
-- the mouse.  Arrows: pan.  Space: tour now.  Left alone, it tours.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/29-atlas-of-the-deep.scene"
local MIN_ZOOM, MAX_ZOOM = 0.45, 10.0
local INK = { 0.0484, 0.0222, 0.0100 }
local SEA = { 0.0273, 0.0742, 0.0953 }
local STOPS = {
    { 0.0, 0.0, 0.48 },
    { -588.0, -198.6, 1.6 },
    { -221.5, 421.9, 1.6 },
    { -60.0, -330.0, 3.0 },
    { -60.0, -330.0, 8.5 },
    { 0.0, 0.0, 0.48 },
}
-- name tier, zoom it fades in from, to, fades out from, to
local TIERS = {
    { "label_ocean", 0.0, 0.0, 0.9, 1.6, SEA },
    { "label_isle", 0.0, 0.0, 5.0, 7.0, INK },
    { "label_town", 1.0, 1.5, 99, 99, INK },
    { "label_detail", 3.5, 5.0, 99, 99, INK },
}

local post_on = nav.post_all_on(SCENE)
local captions = true
local status, cam
local x, y, zoom = 0.0, 0.0, 0.48
local tx, ty, tz = 0.0, 0.0, 0.48
local quiet, touring, stop, held = 0.0, true, 1, 0.0
local labels = {}

local function smooth(a, b, v)
    if v <= a then return 0 end
    if v >= b then return 1 end
    local t = (v - a) / (b - a)
    return t * t * (3 - 2 * t)
end

local function tier_alpha(t, z)
    local fade_in = (t[3] > t[2]) and smooth(t[2], t[3], z) or 1
    return fade_in * (1 - smooth(t[4], t[5], z))
end

function init(entity)
    status = Entity.find_by_name("Status")
    cam = Entity.find_by_name("Camera")
    for i, t in ipairs(TIERS) do
        labels[i] = { entities = Entity.find_by_tag(t[1]) or {}, alpha = -1 }
    end
end

function update(entity, dt)
    nav.tick(SCENE)
    nav.post_keys(post_on)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then touring, stop, held = true, 1, 0 end

    local wheel = Input.get_mouse_wheel() or 0
    local pan_x, pan_y = 0, 0
    if Input.is_key_pressed("Left") then pan_x = -1 end
    if Input.is_key_pressed("Right") then pan_x = 1 end
    if Input.is_key_pressed("Up") then pan_y = 1 end
    if Input.is_key_pressed("Down") then pan_y = -1 end
    if wheel ~= 0 or pan_x ~= 0 or pan_y ~= 0 then
        touring, quiet = false, 0
        if wheel ~= 0 then
            -- Toward the mouse: the point under it stays under it.
            local mx, my = Input.get_mouse_world_position()
            local nz = math.max(MIN_ZOOM, math.min(MAX_ZOOM, tz * (1.18 ^ wheel)))
            tx = mx + (tx - mx) * tz / nz
            ty = my + (ty - my) * tz / nz
            tz = nz
        end
        tx = tx + pan_x * dt * 600 / tz
        ty = ty + pan_y * dt * 600 / tz
    else
        quiet = quiet + dt
        if quiet > 6 then touring = true end
    end
    if touring then
        local s = STOPS[stop]
        tx, ty, tz = s[1], s[2], s[3]
        held = held + dt
        if held > 4.5 then
            held = 0
            stop = stop % #STOPS + 1
        end
    end

    -- Ease, the zoom in log space so it travels evenly.
    local k = 1 - math.exp(-dt * 2.2)
    x = x + (tx - x) * k
    y = y + (ty - y) * k
    zoom = math.exp(math.log(zoom) + (math.log(tz) - math.log(zoom)) * k)
    if cam then
        Transform.set_position(cam, x, y)
        Camera.set_zoom(zoom)
    end

    for i, t in ipairs(TIERS) do
        local a = tier_alpha(t, zoom)
        local l = labels[i]
        if math.abs(a - l.alpha) > 0.01 then
            l.alpha = a
            for _, e in ipairs(l.entities) do
                Text.set_color(e, t[6][1], t[6][2], t[6][3], a)
            end
        end
    end
    if status then
        UI.set_text(status, "zoom x" .. string.format("%.1f", zoom / 0.48) .. (touring and "   touring" or ""))
    end
end
